:root {
  --ink: #070b10;
  --ink-2: #0b1118;
  --panel: rgba(9, 15, 21, 0.76);
  --panel-solid: #0c131b;
  --line: rgba(156, 190, 208, 0.16);
  --line-hot: rgba(255, 180, 92, 0.55);
  --text: #d9e4e8;
  --muted: #7f939e;
  --dim: #536671;
  --amber: #ffb45c;
  --amber-soft: #ffd29a;
  --red: #ff5b56;
  --cyan: #74d9de;
  --green: #83d6a6;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --font-display: "Bahnschrift Condensed", "DIN Condensed", "Arial Narrow", "Roboto Condensed", sans-serif;
  --font-ui: "Bahnschrift", "DIN Alternate", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --font-mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", Consolas, monospace;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
html { background: var(--ink); }
body {
  overflow: hidden;
  background: radial-gradient(circle at 50% 45%, #0e1620 0%, #05080c 70%);
  color: var(--text);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}
button { font: inherit; color: inherit; }
canvas { display: block; }

#app { position: fixed; inset: 0; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; cursor: none; touch-action: none; }

#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 48%, transparent 36%, rgba(2, 5, 8, 0.18) 65%, rgba(2, 4, 7, 0.7) 100%),
    linear-gradient(180deg, rgba(1, 3, 5, 0.28), transparent 18%, transparent 82%, rgba(1, 3, 5, 0.4));
}
#grain {
  position: absolute; inset: -60px; pointer-events: none; z-index: 3; opacity: 0.055;
  mix-blend-mode: overlay;
  background-repeat: repeat;
  animation: grainShift 0.7s steps(2) infinite;
}
@keyframes grainShift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-18px, 12px, 0); }
  50% { transform: translate3d(14px, -9px, 0); }
  75% { transform: translate3d(-9px, -16px, 0); }
  100% { transform: translate3d(11px, 14px, 0); }
}
#damageFlash {
  position: absolute; inset: 0; pointer-events: none; z-index: 4; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(180, 20, 20, 0.22) 70%, rgba(255, 42, 38, 0.62) 100%);
  transition: opacity 0.12s linear;
}
#lowHealth {
  position: absolute; inset: 0; pointer-events: none; z-index: 3; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(130, 6, 8, 0.26) 78%, rgba(150, 8, 10, 0.48) 100%);
  animation: lowPulse 1.35s ease-in-out infinite;
  transition: opacity 0.3s;
}
#lowHealth.active { opacity: 1; }
@keyframes lowPulse { 0%, 100% { opacity: 0.55; } 50% { opacity: 1; } }

.hidden { display: none !important; }
.eyebrow {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  display: flex; align-items: center; gap: 8px;
  white-space: nowrap;
}
.status-dot, .blink-dot {
  width: 6px; height: 6px; border-radius: 50%; background: var(--amber);
  box-shadow: 0 0 8px var(--amber); display: inline-block;
  animation: dotPulse 1.6s ease-in-out infinite;
}
@keyframes dotPulse { 0%, 100% { opacity: 0.5; transform: scale(0.8); } 50% { opacity: 1; transform: scale(1); } }

/* ------------------------------- HUD ------------------------------- */
#hud { position: absolute; inset: 0; z-index: 6; pointer-events: none; }
#hud button { pointer-events: auto; }
.hud-top {
  position: absolute; top: 0; left: 0; right: 0;
  display: flex; align-items: flex-start; justify-content: space-between;
  padding: calc(18px + var(--safe-t)) calc(22px + var(--safe-r)) 0 calc(22px + var(--safe-l));
  gap: 18px;
}
.hud-panel {
  background: linear-gradient(135deg, rgba(11, 18, 25, 0.86), rgba(6, 11, 16, 0.64));
  border: 1px solid var(--line);
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.hud-panel::before {
  content: ""; position: absolute; left: -1px; top: 8px; width: 2px; height: 22px;
  background: var(--amber); box-shadow: 0 0 10px rgba(255, 180, 92, 0.7);
}
.mission-card { position: relative; width: 246px; padding: 14px 16px 13px; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%); }
.mission-card h1 {
