  letter-spacing: 0.055em; font-weight: 700; color: #eef4f5;
}
.mission-card h1 span { color: var(--amber); }
.mission-meta { display: flex; gap: 8px; align-items: center; font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.11em; color: var(--dim); }
.meta-sep { width: 16px; height: 1px; background: var(--line); }

.compass-wrap { position: absolute; left: 50%; top: calc(14px + var(--safe-t)); transform: translateX(-50%); width: min(460px, 36vw); display: flex; flex-direction: column; align-items: center; gap: 3px; }
#compass { width: 100%; height: 58px; opacity: 0.92; filter: drop-shadow(0 2px 8px rgba(0,0,0,0.5)); }
.room-chip {
  margin-top: -3px; padding: 4px 12px; font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.22em;
  color: var(--amber-soft); background: rgba(8, 13, 18, 0.78); border: 1px solid rgba(255, 180, 92, 0.24);
  border-radius: 2px; text-transform: uppercase; white-space: nowrap;
