}
.threat-wrap { display: flex; align-items: flex-start; gap: 8px; }
.threat-card { position: relative; width: 206px; padding: 12px 12px 10px; }
.threat-row { display: flex; justify-content: space-between; align-items: flex-start; }
.threat-count { font-family: var(--font-display); font-size: 36px; line-height: 0.9; letter-spacing: 0.03em; color: #f2f6f6; margin-top: 2px; }
.threat-count small { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.15em; color: var(--dim); margin-left: 5px; vertical-align: middle; }
