.threat-icon svg { width: 100%; height: 100%; fill: currentColor; }
#minimap { width: 100%; height: 112px; margin-top: 7px; border: 1px solid rgba(137, 170, 184, 0.13); background: rgba(3, 7, 10, 0.5); }
