.legend-you, .legend-clear { width: 5px; height: 5px; border-radius: 50%; display: inline-block; }
.legend-you { background: var(--amber); box-shadow: 0 0 5px var(--amber); }
.legend-clear { background: var(--cyan); margin-left: 8px; }
.hud-buttons { display: flex; flex-direction: column; gap: 6px; }
.icon-btn {
  width: 34px; height: 34px; display: grid; place-items: center; cursor: pointer;
  border: 1px solid var(--line); background: rgba(8, 13, 18, 0.7); color: var(--muted);
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}
