.icon-btn svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn .icon-muted { display: none; }
.icon-btn.muted .icon-sound { display: none; }
.icon-btn.muted .icon-muted { display: block; }
.icon-btn.muted { color: var(--red); }

.hud-bottom {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: flex; align-items: flex-end; justify-content: space-between;
  padding: 0 calc(22px + var(--safe-r)) calc(20px + var(--safe-b)) calc(22px + var(--safe-l));
  gap: 16px;
}
.vitals { position: relative; width: 250px; padding: 11px 14px 10px; }
.vitals-head { display: flex; justify-content: space-between; align-items: baseline; }
.vitals-head > span:last-child { font-family: var(--font-display); font-size: 24px; line-height: 0.9; color: #f2f7f7; }
