/* ------------------------------ Screens ----------------------------- */
.screen { position: absolute; inset: 0; z-index: 10; display: flex; align-items: center; justify-content: center; }
.start-screen {
  padding: calc(24px + var(--safe-t)) calc(28px + var(--safe-r)) calc(20px + var(--safe-b)) calc(28px + var(--safe-l));
  background:
    linear-gradient(90deg, rgba(4, 8, 12, 0.9) 0%, rgba(4, 8, 12, 0.62) 46%, rgba(4, 8, 12, 0.3) 100%),
