}
.start-shell { width: min(1180px, 100%); display: grid; grid-template-columns: minmax(0, 1.08fr) minmax(360px, 0.92fr); gap: clamp(28px, 5vw, 76px); align-items: center; }
.start-copy { max-width: 590px; }
