content.text:
Now main.js. Let's write carefully. This will be long (~1500 lines). We'll do it in parts? Write full file maybe 1000 lines. Need be careful.

Let me draft functions.

Top:
```js
import { generateHouse } from './house.js';
import { buildWorld, stampBlood, drawMinimap, drawPlan, drawCompass } from './world.js';
import { Sound } from './audio.js';
import { clamp, lerp, angleLerp, dist, dist2, raycast, lineBlocked, raySegment, formatTime, circleRectOverlap } from './utils.js';

const $ = (id) => document.getElementById(id);
const dom = {...};
const canvas=..., ctx=...
const sceneCanvas=document.createElement('canvas'), sceneCtx=...
const view={w:0,h:0,dpr:1,zoom:1};
let house=null, world=null;
...
```

Constants.

`coarse = matchMedia...` update on resize maybe.

Seed:
```
const initialSeed = (()=>{ const p = new URLSearchParams(location.search).get('seed'); if(p!==null){const n=parseInt(p,10); if(Number.isFinite(n)) return n>>>0;} return (Math.random()*0xffffffff)>>>0; })();
let seed=initialSeed;
```
`state`.

Need reset player references. Use `state.player`.

`makePlayer`:
```
{
 x:house.spawn.x, y:..., radius:13, vx:0,vy:0,
 hp:100,maxHp:100,armor:75,maxArmor:75,
 aimAngle:0, mag:MAG_SIZE,reserve:RESERVE,
 fireCooldown:0, reloading:false, reloadTimer:0,
 heat:0, hitFlash:0, moving:false, sprint:false,
 autoReload:0
}
```

`prepareRun(rebuild)`:
```
if(rebuild) world=buildWorld(house);
state.player=makePlayer();
state.enemies=house.enemies.map(e=>{const maxHp=e.variant==='heavy'?140:100; return {...e,hp:maxHp,maxHp,alive:true,alert:0,lastSeen:-10,windup:0,burst:0,burstTimer:0,cooldown:0.5+Math.random()*1.2,hitFlash:0,deathTime:0,seen:false,angle:e.patrolAngle,shotCount:0};});
for (const r of house.allRooms) r.cleared=false;
state.bullets=[]; state.tracers=[]; state.particles=[]; state.texts=[];
state.camera={x:state.player.x,y:state.player.y,shake:0};
state.stats={shots:0,hits:0,kills:0,damage:0};
state.runTime=0; state.winTimer=0; state.deathTimer=0; state.killSlow=0; state.timeScale=1;
state.aimTarget=null; state.hitMarker=0; state.killMarker=0; state.damageTimer=99; state.stepTimer=0;
state.currentRoomId=null; state.toastToken=0; hideToast();
state.keys.clear(); state.mouse.down=false; state.mouse.moved=false;
state.touch.move={x:0,y:0,active:false}; state.touch.aim={x:0,y:0,active:false};
resetStickVisuals();
```
`resetStickVisuals` sets knob transform.

`loadHouse(newSeed, build=true)`:
```
seed=newSeed>>>0; house=generateHouse(seed); if(build) world=buildWorld(house);
dom.seedLabel...; plan...
updatePlanStats();
if(build) prepareRun(false); // this uses house
```
But prepareRun resets state and player. For initial menu okay. When loading new house from results, we call prepareRun(false). Fine.
- `prepareRun` uses world; if build false but world from previous, bad. Ensure build true when new house.
- Actually simpler: loadHouse only sets house/world and updates labels. Caller calls prepareRun. Initial calls prepareRun(false).
```
function loadHouse(newSeed, build=true) { seed=...; house=generateHouse(seed); if(build) world=buildWorld(house); update labels; drawPlanNow(); }
```
Then `init`: loadHouse(seed,true); prepareRun(false); state.mode='menu'; ...
- New preview: loadHouse(random,true); prepareRun(false); mode menu.
- Start fresh: loadHouse(random,true); prepareRun(false); mode playing.
- Retry: prepareRun(true).
- Start current: prepareRun(true).
- Note prepareRun(true) rebuilds world with current house.

`beginPlaying()` helper hides screens etc.

`startGame()`.

`showStartScreen` maybe initial only.

`setMode` no.

`newHouseStart()`.

`retryHouse()`.

`pause` etc.

Resize:
```
function resize(){
 view.w=window.innerWidth; view.h=window.innerHeight;
 view.dpr=Math.min(window.devicePixelRatio||1,1.5);
 canvas.width=Math.round(view.w*view.dpr); ...
 canvas.style.width=view.w+'px'...
 sceneCanvas...
 view.zoom=clamp(Math.min(view.w/1250,view.h/760),0.58,1.18);
