 resizeMinimapCanvas(); // each frame ensure
}
```
- If world and player, maybe clamp camera.
- `drawPlanNow` after slight delay? start screen visible; okay.
- Use window.innerWidth not visualViewport? fine.
- On orientation change, same.

`worldToScreen`.

Camera clamp:
```
function clampCamera(cx,cy){
 const halfW=view.w/(2*view.zoom), halfH=view.h/(2*view.zoom);
 let x=cx, y=cy;
 if(WORLD.w<=halfW*2) x=WORLD.w/2; else x=clamp(x,halfW,WORLD.w-halfW);
 ...
 return {x,y};
}
```
Need import WORLD from house.js or house.world. Use `house.world`. Camera function uses house.world. If house null skip.

Menu camera:
- state.player exists. target = player + dir*70. aim oscillates. camera lerp. On initial prepareRun sets camera to player, then update.
- `updateCamera(dt)` with state.mode.

Render loop:
```
let lastTime=performance.now();
function frame(now){
 const raw=Math.min(0.05,(now-lastTime)/1000||0.016); lastTime=now;
 state.time += raw;
 if(state.mode==='playing'||state.mode==='dying') update(raw);
 else if(state.mode==='menu') updateMenu(raw);
 render();
 requestAnimationFrame(frame);
}
```
- On paused/won/dead, no update except maybe particles? Could still render static. For end screen, render still. Fine.
- In menu, update camera and aim; maybe animate particles? no.
- `update(raw)`:
```
const real=raw;
state.timeScale = state.killSlow>0 ? lerp(state.timeScale,0.28,0.2) : lerp(state.timeScale,1,0.08);
state.killSlow=Math.max(0,state.killSlow-real);
const dt=raw*state.timeScale;
if(state.mode==='playing'){
  state.runTime += real;
  updatePlayer(dt);
  updateEnemies(dt);
  updateBullets(dt);
  updateParticles(dt);
  updateTracers(dt);
  updateCamera(real); // use real for smooth camera
  state.damageTimer += real;
  if(state.damageTimer>6 && player.hp>0) player.hp=Math.min(max,hp+12*real);
  updateRooms();
  if(state.winTimer>0){ state.winTimer-=real; if<=0 showResults(true); }
} else if (dying) {
  state.deathTimer-=real; updateParticles(dt); updateBullets(dt); updateCamera(real); if<=0 showResults(false);
}
updateHud();
```
- If winTimer set, state.mode still playing; player can still move/shoot though all dead. Fine. Could set `state.clearing=true` to disable shooting; not needed.
- Enemy update only if mode playing.
- `updatePlayer` calls aim update and firing.
- `updateCamera` uses raw.
- `state.time` increments in frame; use for timers.

`updateMenu(raw)`:
```
const p=state.player;
p.aimAngle = -0.12 + Math.sin(state.time*0.45)*0.32;
state.camera.shake=0;
updateCamera(raw);
```
- Camera target lookahead 50. Fine.

`updatePlayer(dt)`:
- If state.player.hp<=0 return.
- Movement input:
```
let mx=0,my=0;
if(keys has w/arrowup) my-=1...
if touch.move.active && mag>0.15: mx+=touch.x; my+=touch.y
const len=Math.hypot...
if len>1 normalize
const sprint = keys.has('shift')
const speed = sprint?SPRINT:PLAYER_SPEED
p.moving = len>0.08
p.vx = lerp(p.vx, mx*speed, 1-Math.exp(-14*dt))
...
moveWithCollision(p, p.vx*dt, p.vy*dt)
```
- Touch move vector maybe analog magnitude; use raw.
- Aim:
```
if (state.touch.aim.active && mag>0.18) p.aimAngle=atan2(touch.aim.y,touch.aim.x);
else if (state.mouse.moved && !isCoarse) p.aimAngle=angleToMouse;
else if (p.moving && isCoarse && !state.touch.aim.active) p.aimAngle=atan2(my,mx);
```
- For touch if aim stick inactive but moving, aim direction movement. But firing only aim active.
- For desktop, if mouse moved. On menu, aim set separately.
- Update aim target.
- Fire:
```
if ((state.mouse.down && !isCoarse) || (state.touch.aim.active && mag>0.35)) attemptFire();
```
- update cooldown, reload.
- `p.fireCooldown -= dt; p.heat = max(0,p.heat - dt*1.9);`
- reload progress. Use `p.reloadTimer`.
- hitFlash decay: `p.hitFlash = max(0,p.hitFlash-dt*3.5)`.
- footsteps: if moving and stepTimer<=0: sound.footstep(); stepTimer = sprint?0.27:0.4; else stepTimer-=dt. Only if playing. Fine.
- Auto reload if mag==0 and reserve>0 and !reloading and fireCooldown<=0: startReload(); but would instantly reload after last shot. Good.
- Regen handled outside.

`movePlayerWithCollision(p, dx,dy)`:
```
const steps=Math.max(1,Math.ceil(Math.hypot(dx,dy)/5));
for i: p.x+=dx/steps; p.y+=dy/steps; resolveCircle(p, house.collisionRects);
```
resolve:
```
for iter<2:
 for rect of rects:
  const nx=clamp(p.x, rect.x, rect.x+rect.w); ...
  const ddx=p.x-nx, ddy=...
  const d2=...
  if d2 < r*r:
    if d2>0.0001 { const d=sqrt; push = r-d; p.x+=ddx/d*push; p.y+=ddy/d*push; }
    else { // inside
      const left=p.x-rect.x, right=rect.x+rect.w-p.x, top=..., bottom=...
      const m=Math.min(left,right,top,bottom);
      if(m===left) p.x=rect.x-r; else if(m===right) p.x=rect.x+rect.w+r; ...
    }
```
- `collisionRects` includes walls and solid furniture. Some furniture inside room; player can get pushed out.
- Also clamp to world bounds.

Aim mouse:
```
function mouseWorld(){
 return { x: camera.x + (mouse.x - view.w/2)/view.zoom, y: camera.y + (mouse.y - view.h/2)/view.zoom };
}
