function readSeed() {
  const value = new URLSearchParams(location.search).get('seed');
  if (value !== null) {
    const n = Number.parseInt(value, 10);
    if (Number.isFinite(n)) return n >>> 0;
  }
  return (Math.random() * 0xffffffff) >>> 0;
}

