import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
mkdirSync('screenshots', { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => { errors.push('PAGEERROR ' + e.message); console.error('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE ' + m.text()); console.error('CONSOLE', m.text()); } });
page.on('response', r => { if (r.status() >= 400) { errors.push(`HTTP ${r.status()} ${r.url()}`); console.error('HTTP', r.status(), r.url()); } });
await page.goto('http://localhost:3002/?seed=12345', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1200);
await page.screenshot({ path: 'screenshots/start.png' });
console.log('title:', await page.title());
console.log('start visible:', await page.locator('#startScreen').isVisible());
console.log('plan stats:', await page.locator('.plan-stats').innerText());
await page.locator('#startBtn').click();
await page.waitForTimeout(1200);
await page.screenshot({ path: 'screenshots/game.png' });
console.log('hud visible:', await page.locator('#hud').isVisible());
console.log('hostiles:', await page.locator('#hostiles').innerText());
console.log('room:', await page.locator('#roomChip').innerText());
console.log('health:', await page.locator('#healthValue').innerText(), 'ammo:', await page.locator('#ammoMag').innerText());
await page.mouse.move(900, 450);
await page.waitForTimeout(200);
await page.screenshot({ path: 'screenshots/game-aim.png' });
await page.keyboard.down('d');
await page.waitForTimeout(900);
await page.keyboard.up('d');
await page.mouse.down();
await page.waitForTimeout(500);
await page.mouse.up();
await page.waitForTimeout(400);
await page.screenshot({ path: 'screenshots/game-move.png' });
console.log('errors:', errors.length ? errors : 'none');
await browser.close();

