function init() {
  makeGrain();
  bindEvents();
  resize();
  loadHouse(seed, true);
  prepareRun(false);
  state.mode = 'menu';
  state.player.aimAngle = 0;
  updateLabels();
  drawPlanNow();
  requestAnimationFrame(loop);
}

window.__IRONSIGHT__ = {
  get state() { return state; },
  get house() { return house; },
  get world() { return world; },
  get seed() { return seed; },
  startGame,
  retryHouse,
  startNewHouse,
  prepareRun,
  killAll() {
    for (const e of state.enemies) {
      if (e.alive) killEnemy(e, 0);
    }
  },
  clearRoom(id) {
    for (const e of state.enemies) {
      if (e.alive && e.roomId === id) killEnemy(e, 0);
    }
  },
  teleport(x, y) {
    state.player.x = x;
    state.player.y = y;
    state.camera.x = x;
    state.camera.y = y;
  },
  aim(angle) {
    state.player.aimAngle = angle;
  },
  setGodMode(on) {
    this._god = on;
  }
};

init();

