import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });

async function measure(label, url, setup) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto(url, { waitUntil: 'load' });
  await page.waitForTimeout(300);
  await page.locator('#startBtn').click();
  await page.waitForTimeout(500);
  if (setup) await setup(page);
  const r = await page.evaluate(() => new Promise(res => {
    let n = 0; const t = performance.now();
    function f() { n++; if (performance.now() - t < 1500) requestAnimationFrame(f); else res({ fps: +(n / ((performance.now() - t) / 1000)).toFixed(1) }); }
    requestAnimationFrame(f);
  }));
  console.log(label, r);
  await page.close();
}

