await measure('no grain rs0.7', 'http://localhost:3002/?seed=12345&rs=0.7', async (p) => {
  await p.addStyleTag({ content: '#grain,#vignette{display:none!important}' });
});
await measure('no grain no blur rs0.7', 'http://localhost:3002/?seed=12345&rs=0.7', async (p) => {
  await p.addStyleTag({ content: '#grain,#vignette{display:none!important}' });
  await p.evaluate(() => { const g = window.__IRONSIGHT__; g.view.rs = 0.7; });
});
await browser.close();

