function clampCamera(x, y) {
  const halfW = VIEW.w / (2 * VIEW.zoom);
  const halfH = VIEW.h / (2 * VIEW.zoom);
  const w = house ? house.world.w : 1820;
  const h = house ? house.world.h : 1040;
  const padX = Math.min(halfW * 0.55, 300);
  const padY = Math.min(halfH * 0.55, 220);
  const minX = halfW - padX;
  const maxX = w - halfW + padX;
  const minY = halfH - padY;
  const maxY = h - halfH + padY;
  return {
    x: minX >= maxX ? w / 2 : clamp(x, minX, maxX),
    y: minY >= maxY ? h / 2 : clamp(y, minY, maxY)
  };
}

