  console.log('after fire', await page.evaluate(() => {
    const g = window.__IRONSIGHT__;
    return { stats: { ...g.state.stats }, ammo: g.state.player.mag, reserve: g.state.player.reserve, hostiles: g.state.enemies.filter(e => e.alive).length };
