import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });

const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.error('PAGEERROR', e.message); });
await page.goto('http://localhost:3002/?seed=12345', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.screenshot({ path: 'screenshots/mobile-start.png' });
await page.locator('#startBtn').tap();
await page.waitForTimeout(900);
console.log('touch visible', await page.locator('#touchControls').isVisible(), 'rotate hint', await page.locator('#rotateHint').isVisible());
console.log('canvas', await page.evaluate(() => { const c = document.querySelector('#game'); return { w: c.width, h: c.height, css: getComputedStyle(c).width + 'x' + getComputedStyle(c).height, dpr: devicePixelRatio, coarse: matchMedia('(pointer: coarse)').matches }; }));
await page.screenshot({ path: 'screenshots/mobile-portrait.png' });
await page.setViewportSize({ width: 844, height: 390 });
await page.waitForTimeout(800);
console.log('landscape touch visible', await page.locator('#touchControls').isVisible());
await page.screenshot({ path: 'screenshots/mobile-landscape.png' });
console.log('errors', errors.length ? errors : 'none');
await browser.close();

