import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.error('PAGEERROR', e.message); });
await page.goto('http://localhost:3002/?seed=12345', { waitUntil: 'load' });
await page.waitForTimeout(400);
await page.locator('#startBtn').tap();
await page.waitForTimeout(600);

async function stickDrag(id, dx, dy, ms) {
  await page.evaluate(({ id, dx, dy, ms }) => new Promise((resolve) => {
    const el = document.getElementById(id);
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    const opts = { pointerId: 1, pointerType: 'touch', isPrimary: true, bubbles: true, cancelable: true, clientX: cx + dx, clientY: cy + dy, buttons: 1 };
    el.dispatchEvent(new PointerEvent('pointerdown', opts));
    setTimeout(() => {
      el.dispatchEvent(new PointerEvent('pointerup', { ...opts, buttons: 0 }));
      resolve();
    }, ms);
  }), { id, dx, dy, ms });
}

const before = await page.evaluate(() => { const p = window.__IRONSIGHT__.state.player; return { x: p.x, y: p.y, mag: p.mag, shots: window.__IRONSIGHT__.state.stats.shots }; });
await stickDrag('moveStick', 42, 0, 1200);
const afterMove = await page.evaluate(() => { const p = window.__IRONSIGHT__.state.player; return { x: p.x, y: p.y, touch: { ...window.__IRONSIGHT__.state.touch.move } }; });
console.log('move', before, '->', afterMove);
await stickDrag('aimStick', 0, -42, 700);
const afterAim = await page.evaluate(() => { const g = window.__IRONSIGHT__; return { shots: g.state.stats.shots, mag: g.state.player.mag, aim: g.state.player.aimAngle, touch: { ...g.state.touch.aim } }; });
console.log('aim/fire', afterAim);
await page.locator('#touchReload').tap();
await page.waitForTimeout(200);
console.log('reloading', await page.evaluate(() => window.__IRONSIGHT__.state.player.reloading));
await page.locator('#pauseBtn').tap();
await page.waitForTimeout(300);
console.log('paused', await page.evaluate(() => window.__IRONSIGHT__.state.mode), await page.locator('#pauseScreen').isVisible());
console.log('errors', errors.length ? errors : 'none');
await browser.close();

